def note_lesen(text):
    t = text.strip().replace(",", ".")
    try:
        n = float(t)
    except ValueError:
        return None, "Bitte eine Zahl " \
            "von 1 bis 5 eingeben."
    if not 1 <= n <= 5:
        return None, "Noten gehen " \
            "von 1 bis 5."
    return n, ""

for e in [" 2,5", "6", "gut"]:
    print(note_lesen(e))
